    vocab:[["INN","a small hotel where you can eat and sleep"],["SAILOR","a person who works on a ship"],["CHEST","a big strong box for keeping things in"],["SCAR","a mark on the skin from an old cut"],["RUM","a strong alcoholic drink that sailors liked"],["PIRATE","a sailor who robs other ships"],["CAPTAIN","the person in charge of a ship"],["SONG","words that you sing"],["AFRAID","frightened"],["DOCTOR","a person who helps ill people"],["PROMISE","to say that you will surely do something"],["CLIFF","a high steep rock next to the sea"]],
    comp:[["Who tells the story?",["Doctor Livesey","Jim Hawkins","Long John Silver","Billy Bones"],1,"Jim says the doctor and the squire asked him to write it."],["Where does Jim live?",["On a ship","At the Admiral Benbow Inn","In Bristol","On an island"],1,"A lonely inn near the cliffs and the sea."],["What does the old sailor bring with him?",["A dog","A large sea chest","A map","A parrot"],1,"And he never lets anybody touch it."],["What does he ask Jim to do?",["Clean his room","Watch for a sailor with one leg","Cook his food","Write a letter"],1,"He pays him a little money every month."],["What does the captain drink?",["Water","Tea","Rum","Milk"],2,"Too much of it, every day."],["Who is not afraid of the captain?",["Jim's father","Doctor Livesey","The other sailors","Nobody"],1,"He tells him he will die if he drinks more rum."],["What happens to Jim's father?",["He goes away","He becomes ill","He fights the captain","He calls the police"],1,"He is worried about the captain and becomes ill."],["What does the captain sing about?",["The sea","Fifteen men on a dead man's chest","His family","A ship"],1,"'Yo-ho-ho and a bottle of rum!'"]],
    tf:[["Jim lives at an inn near the sea.",true,"The Admiral Benbow, near the cliffs."],["The old sailor is friendly and quiet.",false,"He drinks, sings loudly and frightens everybody."],["The captain pays Jim to watch for a one-legged sailor.",true,"A little money every month."],["Everybody is afraid of the captain.",false,"Doctor Livesey is not."],["The captain pays for his room every week.",false,"He stays for weeks and never pays again."],["Jim's father becomes ill.",true,"He is worried and his health gets worse."]],
    rw:[["The old sailor had a scar on one cheek.",0,"Right — from an old cut."],["The captain paid Jim every month.",0,"Right — to watch for the sailor with one leg."],["The inn was in the middle of a big city.",1,"Wrong — it was a lonely place near the sea."],["The captain was sixty years old.",2,"Doesn't say — we don't know his age."],["Doctor Livesey was also a magistrate.",0,"Right — and he told the captain he could send him to prison."],["The captain had a dog with him.",1,"Wrong — he had a sea chest."],["Jim's mother worked at the inn too.",0,"Right — the family ran the inn together."],["The captain often looked at the sea with a telescope.",0,"Right — he watched for ships and for sailors."]],
    halves:[["Jim Hawkins lives","at the Admiral Benbow Inn with his parents."],["One day an old sailor arrives","with a big sea chest."],["The captain pays Jim","to watch for a sailor with one leg."],["He drinks rum and sings","about fifteen men on a dead man's chest."],["The other customers are afraid,","but they come back to listen to him."],["Doctor Livesey is not afraid","and tells him to stop drinking."],["The captain stays for weeks","and never pays for his room."],["Jim's father is worried","and becomes ill."]],
